import { DurableObject } from 'cloudflare:workers'

export interface Env {
  ASSETS: Fetcher
  CITY: DurableObjectNamespace<CityDO>
}

type Holding = {
  id: string
  ticker: string
  symbol?: string
  nickname: string
  avgPrice: number
  quantity: number
  message: string
  createdAt: number
}
type ChatMessage = {
  id: string
  nickname: string
  ticker: string
  text: string
  createdAt: number
}
type CityState = {
  version: number
  holdings: Holding[]
  prices: Record<string, number>
  symbols: Record<string, string>
  messages: ChatMessage[]
  lastPriceUpdate: number
}

// 이 값을 올리면 배포 시 기존 공유 도시가 1회 초기화된다.
const STATE_VERSION = 2

// 기본은 빈 도시 — 입주는 실제 친구들이 직접.
function seedState(): CityState {
  return {
    version: STATE_VERSION,
    holdings: [],
    prices: {},
    symbols: {},
    messages: [
      {
        id: 'welcome',
        nickname: '시스템',
        ticker: '',
        text: '물림 시티에 오신 걸 환영합니다! "입주하기"로 종목과 평단을 올려보세요 🏙️',
        createdAt: 0,
      },
    ],
    lastPriceUpdate: 0,
  }
}

export class CityDO extends DurableObject<Env> {
  state: CityState

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env)
    this.state = seedState()
    ctx.blockConcurrencyWhile(async () => {
      const saved = await ctx.storage.get<CityState>('state')
      if (saved && saved.version === STATE_VERSION) {
        this.state = saved
      } else {
        // 버전이 다르거나 최초면 빈 도시로 초기화
        await ctx.storage.put('state', this.state)
      }
      // 첫 생성 시 곧바로 시세 1회 갱신 + 이후 하루 1회
      if ((await ctx.storage.getAlarm()) == null) {
        await ctx.storage.setAlarm(Date.now() + 4000)
      }
    })
  }

  async fetch(request: Request): Promise<Response> {
    if (request.headers.get('Upgrade') === 'websocket') {
      const pair = new WebSocketPair()
      const [client, server] = Object.values(pair)
      this.ctx.acceptWebSocket(server)
      server.send(JSON.stringify({ type: 'state', state: this.state }))
      return new Response(null, { status: 101, webSocket: client })
    }
    return Response.json(this.state)
  }

  async webSocketMessage(_ws: WebSocket, message: string | ArrayBuffer) {
    let msg: any
    try {
      msg = JSON.parse(typeof message === 'string' ? message : '')
    } catch {
      return
    }
    await this.handle(msg)
  }

  private pushMsg(nickname: string, ticker: string, text: string) {
    this.state.messages.push({
      id: crypto.randomUUID(),
      nickname,
      ticker,
      text,
      createdAt: Date.now(),
    })
  }

  private async handle(msg: any) {
    const s = this.state
    switch (msg?.t) {
      case 'add': {
        const h = msg.holding ?? {}
        if (!h.ticker || !(h.avgPrice > 0)) return
        const holding: Holding = {
          id: crypto.randomUUID(),
          ticker: String(h.ticker).slice(0, 24),
          symbol: h.symbol ? String(h.symbol).slice(0, 20) : undefined,
          nickname: String(h.nickname || '익명개미').slice(0, 20),
          avgPrice: Number(h.avgPrice),
          quantity: Number(h.quantity) || 0,
          message: String(h.message || '').slice(0, 60),
          createdAt: Date.now(),
        }
        s.holdings.push(holding)
        if (s.prices[holding.ticker] == null) s.prices[holding.ticker] = holding.avgPrice
        if (holding.symbol) s.symbols[holding.ticker] = holding.symbol
        this.pushMsg(holding.nickname, holding.ticker, String(msg.entryText || `${holding.ticker} 입주!`).slice(0, 80))
        break
      }
      case 'chat': {
        this.pushMsg(
          String(msg.nickname || '익명개미').slice(0, 20),
          String(msg.ticker || '').slice(0, 24),
          String(msg.text || '').slice(0, 200),
        )
        break
      }
      case 'price': {
        const p = Number(msg.price)
        if (msg.ticker && p > 0) s.prices[String(msg.ticker)] = p
        break
      }
      case 'updatePrices': {
        await this.updatePrices()
        break
      }
      default:
        return
    }
    if (s.holdings.length > 300) s.holdings = s.holdings.slice(-300)
    if (s.messages.length > 120) s.messages = s.messages.slice(-120)
    await this.persistAndBroadcast()
  }

  private async persistAndBroadcast() {
    await this.ctx.storage.put('state', this.state)
    const snap = JSON.stringify({ type: 'state', state: this.state })
    for (const ws of this.ctx.getWebSockets()) {
      try {
        ws.send(snap)
      } catch {
        /* 닫힌 소켓 무시 */
      }
    }
  }

  private async updatePrices() {
    const tickers = new Set(this.state.holdings.map((h) => h.ticker))
    const entries = Object.entries(this.state.symbols).filter(([t]) => tickers.has(t))
    const report: string[] = []
    for (const [ticker, sym] of entries) {
      try {
        const v = await fetchPrevClose(sym)
        if (Number.isFinite(v)) {
          this.state.prices[ticker] = Math.round(v * 100) / 100
          report.push(`${ticker} ${this.state.prices[ticker]}`)
        }
      } catch {
        /* 개별 실패 무시 */
      }
    }
    this.state.lastPriceUpdate = Date.now()
    if (report.length) this.pushMsg('시스템', '', `📈 전일 종가 갱신 — ${report.join(' · ')}`)
  }

  async alarm() {
    await this.updatePrices()
    await this.persistAndBroadcast()
    await this.ctx.storage.setAlarm(Date.now() + 24 * 3600 * 1000)
  }
}

async function fetchPrevClose(symbol: string): Promise<number> {
  const url = `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(
    symbol,
  )}?range=5d&interval=1d`
  const res = await fetch(url, {
    headers: { 'User-Agent': 'Mozilla/5.0', Accept: 'application/json' },
  })
  if (!res.ok) throw new Error(`http ${res.status}`)
  const data: any = await res.json()
  const meta = data?.chart?.result?.[0]?.meta
  const v = meta?.chartPreviousClose ?? meta?.previousClose ?? meta?.regularMarketPrice
  if (typeof v !== 'number') throw new Error('parse')
  return v
}

export default {
  async fetch(request, env): Promise<Response> {
    const url = new URL(request.url)
    if (url.pathname === '/api/ws' || url.pathname === '/api/state') {
      const room = url.searchParams.get('room') || 'global'
      return env.CITY.getByName(room).fetch(request)
    }
    return env.ASSETS.fetch(request)
  },
} satisfies ExportedHandler<Env>
